import React from 'react';

const Question = ({ questionText, answerChoices, onAnswerSelected, selectedAnswer }) => {
    return (
        <div className="question-container">
            <h2>{questionText}</h2>
            <ul>
                {answerChoices.map((choice, index) => (
                    <li
                        key={index}
                        onClick={() => onAnswerSelected(index)}
                        className={`answer ${selectedAnswer === index ? 'selected' : ''}`}
                    >
                        {choice}
                    </li>
                ))}
            </ul>
        </div>
    );
};

const questions = [
    {
        question: "What is the capital of France?",
        answers: ["Berlin", "Madrid", "Paris", "Rome"],
        correctAnswer: 2, // Index of the correct answer
    },
    {
        question: "Which programming language is used for web development?",
        answers: ["Python", "JavaScript", "C++", "Java"],
        correctAnswer: 1,
    },
    {
        question: "What is the largest planet in our solar system?",
        answers: ["Earth", "Mars", "Jupiter", "Saturn"],
        correctAnswer: 2,
    },
    {
        question: "Who wrote 'Romeo and Juliet'?",
        answers: ["Charles Dickens", "William Shakespeare", "Mark Twain", "Jane Austen"],
        correctAnswer: 1,
    },
    {
        question: "What is the boiling point of water at sea level?",
        answers: ["90°C", "100°C", "110°C", "120°C"],
        correctAnswer: 1,
    },
];

export default questions;
